#pragma once

#include <gtk/gtk.h>

/* Styling: loads sfe's own stylesheet, follows the GTK theme and hot-reloads
 * the user's ~/.config/gtk-3.0/gtk.css (and the files next to it that it
 * usually @imports, e.g. colors generated by Noctalia, matugen or pywal). */

/* Call once after GTK is initialized. */
void sfe_theme_init(void);

/* Scales all text (and, through font-relative sizes, most of the UI), the
 * icons made with sfe_scaled_icon_new() and the pixel sizes in style.css. */
void sfe_theme_set_scale(double scale);
double sfe_theme_get_scale(void);

/* `base_px` times the scale. */
int sfe_theme_scaled(int base_px);

/* An icon `base_px` wide at scale 1 that follows the scale. */
GtkWidget* sfe_scaled_icon_new(const char* icon_name, int base_px);

/* The GtkIconSize nearest to `base_px` scaled (for cell renderers, which
 * take no pixel size). */
GtkIconSize sfe_theme_icon_size_near(int base_px);
